import {combinationCard} from './gallery-renderer.js';
import {products,finishes,accessories,byId,compatibility,validateConfiguration,filterProducts,productSvg,doorStyleSvg,materialReferences} from './catalog-data.js';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}};
const write=(key,v)=>{try{localStorage.setItem(key,JSON.stringify(v));return true;}catch{return false;}};
// Navigation preview changes never select a product or finish.
$$('[data-nav-image]').forEach(link=>{const update=()=>{const panel=$('.nav-product-preview',link.closest('.mega'));if(!panel)return;$('img',panel).src='/assets/'+link.dataset.navImage;$('img',panel).alt=link.dataset.navTitle+' illustrative preview';$('h3',panel).textContent=link.dataset.navTitle;$('p',panel).textContent=link.dataset.navCopy;panel.href=link.href;};link.addEventListener('mouseenter',update);link.addEventListener('focus',update);});
$$('[data-menu]').forEach(button=>{const open=()=>{if(innerWidth<=1000)return;$$('.mega').forEach(panel=>panel.hidden=panel.id!=='mega-'+button.dataset.menu);$$('[data-menu]').forEach(b=>b.setAttribute('aria-expanded',String(b===button)));};button.addEventListener('mouseenter',open);button.addEventListener('keydown',e=>{if(e.key==='ArrowDown'){e.preventDefault();if(button.getAttribute('aria-expanded')!=='true')button.click();$('a',$('#mega-'+button.dataset.menu))?.focus();}});});
const path=location.pathname;$$('[data-menu]').forEach(button=>{const key=button.dataset.menu;const current={shop:['/cabinets/','/chicago-kitchen-cabinets/'],finishes:['/colors-materials/'],storage:['/storage-accessories/'],projects:['/projects/'],how:['/how-it-works/','/start-order/'],local:['/showroom/','/locations/']}[key];if(current?.some(p=>path.startsWith(p)))button.dataset.current='true';});
if($('[data-cabinet-gallery]')){
 const gallery=$('[data-cabinet-gallery]'),params=new URLSearchParams(location.search),defaults=gallery.dataset.defaultCategory;
 const state={category:params.get('category')||defaults||'',storage:params.get('storage')||'',finish:params.get('finish')||'natural-oak',style:params.get('style')||'Shaker',width:params.get('width')||''};
 if(!['','base','wall','tall'].includes(state.category))state.category=defaults||'';if(!accessories.some(a=>a.id===state.storage))state.storage='';if(!finishes.some(f=>f.id===state.finish))state.finish='natural-oak';if(!['Shaker','Slab'].includes(state.style))state.style='Shaker';
 const choices=new Map();
 const options=p=>{const prior=choices.get(p.id)||{};const a=accessories.find(a=>a.id===state.storage);const allowed=a?p.widths.filter(w=>compatibility(p,w,a).ok):p.widths;const width=allowed.includes(prior.width)?prior.width:allowed.includes(Number(state.width))?Number(state.width):allowed[0]||p.widths[0];const result={width,finish:state.finish,style:state.style,storage:state.storage||prior.storage||'',forceStorage:!!state.storage};choices.set(p.id,{width,storage:result.storage});return result;};
 function renderCard(card){const p=byId(card.dataset.component);card.innerHTML=combinationCard(p,options(p));}
 function apply(){const ids=new Set(filterProducts({category:state.category,storage:state.storage}).map(p=>p.id));$$('[data-component]',gallery).forEach(card=>{card.hidden=!ids.has(card.dataset.component);if(!card.hidden)renderCard(card);});for(const key of ['category','storage','finish','style'])$$('[data-gallery-'+key+']',gallery).forEach(b=>b.setAttribute('aria-pressed',String(b.dataset['gallery'+key[0].toUpperCase()+key.slice(1)]===state[key])));$('#component-count').textContent=ids.size+' cabinet combination'+(ids.size===1?'':'s')+(state.storage?' for '+accessories.find(a=>a.id===state.storage).purpose.toLowerCase():' to explore');$('#component-empty').hidden=ids.size!==0;const url=new URL(location.href);for(const key of ['category','storage','finish','style']){if(state[key])url.searchParams.set(key,state[key]);else url.searchParams.delete(key);}history.replaceState(null,'',url);}
 function reset(){state.category='';state.storage='';state.finish='natural-oak';state.style='Shaker';state.width='';choices.clear();apply();}
 gallery.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;for(const key of ['category','storage','finish','style']){const attr='gallery'+key[0].toUpperCase()+key.slice(1);if(b.dataset[attr]!==undefined){state[key]=b.dataset[attr];apply();return;}}
 if(b.id==='clear-component-filters'||b.hasAttribute('data-gallery-reset'))return reset();
 const card=b.closest('[data-component]');if(!card)return;const p=byId(card.dataset.component),prior=choices.get(p.id)||{};
 if(b.hasAttribute('data-combo-width')){prior.width=Number(b.dataset.comboWidth);choices.set(p.id,prior);if(state.storage&&!compatibility(p,prior.width,accessories.find(a=>a.id===state.storage)).ok){state.storage='';apply();}else renderCard(card);card.querySelector('[data-combo-width="'+prior.width+'"]').focus({preventScroll:true});}
 if(b.hasAttribute('data-combo-storage')){prior.storage=b.dataset.comboStorage;choices.set(p.id,prior);if(state.storage){state.storage='';apply();}else renderCard(card);card.querySelector('[data-combo-storage="'+prior.storage+'"]').focus({preventScroll:true});}
 });apply();
}
const root=$('#configuration-step');
if(root){
 const key='amber-cabinet-project-v1';const labels=['Cabinet type','Dimensions','Finish & construction','Storage','Review','Quote request'];
 const blank=()=>({product:'',width:null,depth:null,height:null,style:'',finish:'',doorMaterial:'',boxMaterial:'',accessories:[],quantity:1,customSize:'',notes:'',step:0});
 let config=blank(),project=[],contact={},helpOnly=false,selectedTypes=[],cabinetDrafts={};let halted=false;let saved=read(key,null);let timer;let flowNotice="";let removedCabinet=null;let removalMessage="";
 const save=()=>{rememberCabinet();const ok=write(key,{config,project,contact,helpOnly,selectedTypes,cabinetDrafts,updated:new Date().toISOString()});if(!ok&&!halted){halted=true;$('#configuration-error').hidden=false;$('#configuration-error').textContent='Browser storage is unavailable. Download your reference before leaving.';}updateSummary();};
 const signature=c=>JSON.stringify(['product','width','depth','height','style','finish','doorMaterial','boxMaterial','quantity','accessories','customSize'].map(k=>c?.[k]));
 const keyOf=c=>c?.instanceId||c?.product||'';
 const draftFor=id=>keyOf(config)===id?config:cabinetDrafts[id]||project.find(c=>keyOf(c)===id);
 const requestKeys=()=>selectedTypes.flatMap(product=>{const keys=[...new Set([...Object.entries(cabinetDrafts).filter(([,d])=>d.product===product).map(([key])=>key),...project.filter(c=>c.product===product).map(keyOf),...(config.product===product?[keyOf(config)]:[])])];return keys.length?keys:[product];});
 const cabinetLabel=c=>{const keys=requestKeys().filter(key=>(draftFor(key)?.product||key)===c.product);return (byId(c.product)?.name||'Cabinet')+(keys.length>1?' · Version '+(keys.indexOf(keyOf(c))+1):'');};
 const pendingType=()=>requestKeys().find(id=>id!==keyOf(config)&&(!project.some(c=>keyOf(c)===id)||(cabinetDrafts[id]&&signature(cabinetDrafts[id])!==signature(project.find(c=>keyOf(c)===id)))));
 const rememberCabinet=()=>{if(config.product)cabinetDrafts[keyOf(config)]=structuredClone(config);};
 function openCabinet(id){rememberCabinet();const prior=cabinetDrafts[id];if(prior){config={...blank(),...structuredClone(prior)};helpOnly=false;}else{const completed=project.find(c=>keyOf(c)===id);if(completed){config={...blank(),...structuredClone(completed),editIndex:project.indexOf(completed)};}else{const notes=config.notes;config=blank();config.notes=notes;setProduct(id);}}go(1);}
 const restoreBatch=()=>{selectedTypes=[...new Set((saved.selectedTypes||[saved.config.product]).filter(id=>byId(id)))];cabinetDrafts=saved.cabinetDrafts&&typeof saved.cabinetDrafts==='object'?saved.cabinetDrafts:{};};
 const getFinish=()=>finishes.find(f=>f.id===config.finish);
 const configRows=c=>{const p=byId(c.product),f=finishes.find(f=>f.id===c.finish);return [['Cabinet',c.product?cabinetLabel(c):p?.name],['Dimensions',c.width?`${c.width} W × ${c.depth} D × ${c.height} H inches`:null],['Door style',c.style],['Color',f?.name],['Door material',c.doorMaterial],['Box material',c.boxMaterial],['Accessories',(c.accessories||[]).map(id=>accessories.find(a=>a.id===id)?.name).filter(Boolean).join(', ')],['Quantity',c.product?c.quantity:null],['Custom-size inquiry',c.customSize]].filter(([,v])=>v!==undefined&&v!==null&&v!=='');};
 const reference=()=>{const entries=project.length?project:[config];return 'AMBER LEAF — CABINET PLAN\n\nSELECTED CABINET TYPES\n'+selectedTypes.map(id=>byId(id)?.name).filter(Boolean).join('\n')+'\n\n'+(helpOnly?'DESIGN HELP REQUEST\n':'')+entries.map((c,i)=>'CABINET '+(i+1)+'\n'+configRows(c).map(([k,v])=>k+': '+v).join('\n')).join('\n\n')+'\n\nPRICING\nCabinet subtotal: Quote required\nFinishes: Quote required\nAccessories: Quote required\nDesign, delivery and installation: Scope and quote required\nTotal: Quote required\nTax, countertops and appliances excluded unless expressly quoted.\n\nCONTACT\n'+Object.entries(contact).filter(([,v])=>v).map(([k,v])=>k+': '+v).join('\n')+'\n\nNOTES\n'+config.notes+'\n\nIllustrative configuration; factory confirmation required for dimensions, materials and accessory fit. Not a submitted request, approved quote or placed order.';};
 const download=()=>{const url=URL.createObjectURL(new Blob([reference()],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='amber-leaf-cabinet-plan.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('#download-project').addEventListener('click',download);
 const rowsHTML=c=>configRows(c).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('');
 function updateSummary(){const p=config.step===0?null:byId(config.product);$('#configuration-summary').innerHTML=`<strong class="quote-total">Quote required</strong><small>Final pricing follows specification review.</small>${removalMessage?'<div class="cabinet-removal-feedback" role="status"><p>'+esc(removalMessage)+'</p>'+(removedCabinet?'<button type="button" id="undo-cabinet-removal">Undo removal</button>':'')+'</div>':''}${p?`<div class="config-mini-preview">${productSvg(p,{width:config.width,depth:config.depth,height:config.height,style:config.style,finish:config.finish})}</div>`:''}${p?'<dl>'+rowsHTML(config)+'</dl>':''}${requestKeys().length?'<div class="selected-types-summary"><h3>Cabinet versions · '+requestKeys().length+'</h3><ul>'+requestKeys().map(id=>{const draft=draftFor(id)||{product:id,quantity:1};return '<li><button type="button" class="request-cabinet-switch" data-switch-cabinet="'+id+'" '+(keyOf(config)===id?'aria-current="true"':'')+'><strong>'+esc(cabinetLabel(draft))+'</strong><span>'+(finishes.find(f=>f.id===draft.finish)?.name||'Color not chosen')+' · Qty '+draft.quantity+'</span><small>'+(keyOf(config)===id?'Currently editing':project.some(c=>keyOf(c)===id)?'View or change this version':'Choose this version’s finish')+'</small></button><button type="button" class="remove-plan-cabinet" data-remove-cabinet="'+id+'" aria-label="Remove '+esc(cabinetLabel(draft))+' from plan"><svg aria-hidden="true" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.4"><path d="M3 5H17M7 5V3H13V5M5 5L6 17H14L15 5M8 8V14M12 8V14"/></svg>Remove</button></li>';}).join('')+'</ul></div>':''}${helpOnly?'<p>Design help requested</p>':''}<p>${project.length} cabinet configuration${project.length===1?'':'s'} in your project</p><details><summary>Itemized price status</summary><dl>${['Cabinet subtotal','Finish upgrades','Accessories','Design fees','Delivery','Installation','Total'].map(k=>`<dt>${k}</dt><dd>Quote required</dd>`).join('')}</dl><small>Tax, countertops and appliances excluded unless quoted. Installation requires site and service review.</small></details>`;const summary=$('#configuration-summary');const items=$('.selected-types-summary',summary);if(items){const image=$('.config-mini-preview',summary);const details=image?.nextElementSibling;if(requestKeys().length>1&&image&&details?.tagName==='DL'){const disclosure=document.createElement('details');disclosure.className='current-cabinet-details';const heading=document.createElement('summary');heading.textContent='Current cabinet details';disclosure.append(heading);image.before(disclosure);disclosure.append(image,details);}const target=$('.current-cabinet-details',summary)||$('.config-mini-preview',summary)||summary.querySelector(':scope > p');if(target)summary.insertBefore(items,target);}$('#undo-cabinet-removal')?.addEventListener('click',undoRemoval);$$('[data-remove-cabinet]').forEach(button=>button.addEventListener('click',()=>removeVersion(button.dataset.removeCabinet)));$$('[data-switch-cabinet]').forEach(button=>button.addEventListener('click',()=>{const id=button.dataset.switchCabinet;openCabinet(id);if(config.finish)go(2);}));}
 function error(message,selector){const el=$('#configuration-error');el.hidden=false;el.textContent='Stage '+(config.step+1)+' · '+labels[config.step]+': '+message;el.scrollIntoView({block:'nearest',behavior:'smooth'});const field=selector&&$(selector,root);if(field){field.setAttribute('aria-invalid','true');const focusTarget=field.querySelector('[data-material-choice]')||field;focusTarget.focus();}}
 function setProduct(id){const p=byId(id);config={...config,product:id,width:p.widths[0],depth:p.depths[0],height:p.heights[0],accessories:[]};helpOnly=false;}
 const materialDescriptions={'Painted MDF':'A smooth engineered-fiberboard door with a painted surface.','Laminate on MDF':'A decorative laminate surface over an MDF core.','Oak-look laminate on engineered wood':'A textured laminate surface with the look of oak grain.','Oak veneer on engineered wood':'A thin layer of real oak over an engineered-wood core.','Plywood':'Panels made from bonded layers of wood.','Engineered wood':'Manufactured wood panels. Exact board type is confirmed in your specification.'};
 const materialCards=(values,key)=>'<div class="config-options material-options">'+values.map((value,i)=>'<button type="button" class="config-choice material-choice" role="radio" aria-checked="'+(config[key]===value)+'" tabindex="'+(config[key]===value||(!config[key]&&i===0)?'0':'-1')+'" data-material-choice="'+key+'" data-material-value="'+esc(value)+'">'+(materialReferences[value]?'<img class="material-reference" src="/assets/'+materialReferences[value].image+'" alt="'+esc(materialReferences[value].alt)+'" width="1024" height="1024" loading="lazy">':'')+'<span class="material-area">'+(key==='doorMaterial'?'Visible door face':'Inside cabinet structure')+'</span><strong>'+esc(value)+'</strong><span>'+esc(materialDescriptions[value]||'Specification to confirm.')+'</span>'+(materialReferences[value]?.note?'<span class="caption">'+esc(materialReferences[value].note)+'</span>':'')+'<span class="material-selected" aria-hidden="true">'+(config[key]===value?'✓ Selected':'Choose material')+'</span></button>').join('')+'</div>';
 const choice=(value,title,copy,data,preview='')=>`<button class="config-choice" type="button" data-${data}="${esc(value)}" aria-pressed="${String(config[data]===value)}">${preview}<strong>${esc(title)}</strong><span>${esc(copy)}</span></button>`;
 function go(step){flowNotice='';rememberCabinet();config.step=step;save();render(true);}
 function render(scroll=false){$('.config-progress').hidden=false;$('.plan-nav').hidden=false;const p=byId(config.product),f=getFinish();$('#configuration-error').hidden=true;$('.config-progress').innerHTML=labels.map((label,i)=>`<button type="button" data-config-step="${i}" ${i===config.step?'aria-current="step"':''} ${i>config.step||(helpOnly&&!p&&[1,2,3].includes(i))?'disabled':''}><span>${i+1}.</span>${label}</button>`).join('');$('#config-back').disabled=config.step===0;$('#config-next').hidden=config.step===5;$('#config-next').textContent=config.step===4?(pendingType()&&!helpOnly?'Customize Next Cabinet':'Request a Quote'):config.step===0?'Customize Selected Cabinets':'Continue';let html='';
 if(config.step===0)html=`<h2 tabindex="-1">What cabinet do you need?</h2><p>Select all the cabinet types you need. We’ll customize the size, finish and storage for each one.</p><p class="caption" role="status">${selectedTypes.length} cabinet type${selectedTypes.length===1?'':'s'} selected</p><div class="config-options">${products.map(p=>'<button class="config-choice cabinet-type-choice" type="button" role="checkbox" aria-checked="'+selectedTypes.includes(p.id)+'" data-product="'+p.id+'">'+productSvg(p)+'<span class="cabinet-type-check" aria-hidden="true">'+(selectedTypes.includes(p.id)?'✓':'')+'</span><strong>'+esc(p.name)+'</strong><span>'+esc(p.description)+'</span></button>').join('')}</div><button class="btn outline" id="design-help">I don’t know my cabinet sizes · Request design help</button>`;
 if(config.step===1)html=`<h2 tabindex="-1">Choose a planning size.</h2><p>Illustrative presets, not approved factory sizes. Measurements can be reviewed before manufacturing.</p><div class="config-product-preview">${productSvg(p,{width:config.width,depth:config.depth,height:config.height,technical:true})}</div>${[['width','Width',p.widths],['depth','Depth',p.depths],['height','Cabinet-box height',p.heights]].map(([id,name,values])=>`<fieldset><legend>${name}</legend><div class="config-chips">${values.map(v=>`<button type="button" data-dimension="${id}" data-value="${v}" aria-pressed="${config[id]===v}">${v}″</button>`).join('')}</div></fieldset>`).join('')}<label class="commerce-field">Quantity in this color version<input type="number" id="config-quantity" min="1" max="99" value="${config.quantity}"><small>Units in this line share the same color and materials.</small></label><div id="quantity-color-options"></div><details><summary>Need a nonstandard size?</summary><label class="commerce-field">Custom measurement inquiry<textarea id="custom-size" rows="3" maxlength="600" placeholder="Tell us your desired width, depth or height. This is a request for review.">${esc(config.customSize)}</textarea></label></details>`;
 if(config.step===2)html=`<h2 tabindex="-1">Choose this version’s finish.</h2><p>These choices apply to <strong>${esc(cabinetLabel(config))}</strong> · quantity ${config.quantity}. Other versions keep their own colors.</p><div class="variant-actions"><button type="button" class="textlink" id="another-color">${config.quantity>1?'Split quantity into different colors':'Add one more in another color'}</button>${requestKeys().filter(id=>draftFor(id)?.product===config.product).length>1?'<button type="button" class="textlink" id="remove-current-version">Remove this color version</button>':''}</div><div class="config-options">${finishes.map(f=>choice(f.id,f.name,f.scene,'finish',`<img src="/assets/${f.image}" alt="${f.name} · ${f.scene} · illustrative kitchen finish">`)).join('')}</div><div class="config-current-image">${p?productSvg(p,{width:config.width,depth:config.depth,height:config.height,style:config.style,finish:config.finish}):''}</div><fieldset><legend>Door style</legend><div class="config-options door-style-options">${p.styles.map(v=>choice(v,v,v==='Shaker'?'A raised frame around a recessed center panel':'One smooth, flat face with no frame','style',doorStyleSvg(v,config.finish))).join('')}</div><p class="caption">Illustrative door profiles shown in your chosen color.</p></fieldset><fieldset class="material-fieldset" id="door-material" role="radiogroup" aria-label="Visible door material"><legend>Visible door material</legend><p class="caption">The surface you see and touch on the doors and drawer fronts.</p>${f?materialCards(f.doorMaterials,'doorMaterial'):'<p class="notice">Choose a cabinet color above to see matching door materials.</p>'}</fieldset><fieldset class="material-fieldset" id="box-material" role="radiogroup" aria-label="Cabinet-box material"><legend>Cabinet-box material</legend><p class="caption">The cabinet’s structural panels, behind the doors. This choice is separate from the visible finish.</p>${materialCards(p.boxMaterials,'boxMaterial')}</fieldset><p class="caption">Generated material references, not factory product photos. Surface colors are selected above. Confirm actual samples and manufacturing specifications with the team.</p>`;
 if(config.step===3)html=`<h2 tabindex="-1">Plan the storage inside.</h2><p>Only prototype-compatible selections can be added. The factory must verify internal dimensions and the exact accessory.</p><div class="config-options">${accessories.map(a=>{const match=compatibility(p,config.width,a);return `<article class="compatibility-card ${match.ok?'':'unavailable'}"><img src="/assets/${a.image}" alt="${a.name} illustrative preview" loading="lazy"><h3>${a.purpose}</h3><p>${a.name}</p>${match.ok?`<button type="button" class="btn outline" data-accessory-id="${a.id}" aria-pressed="${config.accessories.includes(a.id)}">${config.accessories.includes(a.id)?'✓ Selected':'Add to configuration'}</button>`:`<p class="compatibility-reason">${esc(match.reason)}</p><button type="button" class="textlink" data-find-storage="${a.id}">Find a suitable cabinet</button>`}</article>`;}).join('')}</div><p class="caption">Accessories are optional. Sink plumbing, corner mechanisms and drawer interiors must be checked separately.</p>`;
 if(config.step===4)html=`<h2 tabindex="-1">Review your cabinet plan.</h2><p>${helpOnly?'We’ll help define the cabinet layout and measurements.':'Check dimensions, construction and storage before requesting a quote.'}</p>${!helpOnly?`<dl class="review-specs">${rowsHTML(config)}</dl><div class="inline-actions">${[['Dimensions',1],['Finishes',2],['Accessories',3]].map(([label,step])=>`<button class="textlink" type="button" data-review-edit="${step}">Edit ${label.toLowerCase()}</button>`).join('')}</div><button type="button" class="btn" id="add-project">${config.editIndex!==undefined?'Update Project':'Add to Project'}</button>`:''}<div id="project-list">${project.map((c,i)=>`<article class="project-line"><h3>${esc(cabinetLabel(c))} · ${c.quantity} requested</h3><p>${c.width} × ${c.depth} × ${c.height}″ · <strong>${esc(finishes.find(f=>f.id===c.finish)?.name)}</strong> · ${esc(c.style)}</p><p class="caption">${esc((c.accessories||[]).map(id=>accessories.find(a=>a.id===id)?.name).filter(Boolean).join(', ')||'No interior accessories')}</p><button class="textlink" data-project-color="${i}">Change color & materials</button><button class="textlink" data-project-edit="${i}">Edit</button><button class="textlink" data-project-remove="${i}">Remove</button></article>`).join('')}</div><div class="inline-actions"><button class="btn outline" id="another-cabinet" ${pendingType()?'hidden':''}>Customize Another Cabinet</button><button class="textlink" id="download-review">Download reference</button></div><p class="notice">Cabinets, finishes, accessories and total: <strong>Quote required.</strong> No product prices are invented. Include design, delivery and installation in your quote scope.</p><label class="commerce-field">Installation preference<select id="installation"><option value="">Not decided</option>${['Supply only','Discuss installation'].map(v=>`<option ${contact.installation===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="commerce-field">Project notes<textarea id="project-notes" maxlength="3000" rows="3">${esc(config.notes)}</textarea></label>`;
 if(config.step===5)html=`<h2 tabindex="-1">Request your personalized quote.</h2><p>Share only what the team needs to review your project.</p><form id="quote-contact"><label class="commerce-field">Name *<input name="name" autocomplete="name" required maxlength="100" value="${esc(contact.name)}"></label><label class="commerce-field">Email *<input name="email" type="email" autocomplete="email" required maxlength="254" value="${esc(contact.email)}"></label><label class="commerce-field">Phone (optional)<input name="phone" type="tel" autocomplete="tel" maxlength="40" value="${esc(contact.phone)}"></label><label class="commerce-field">ZIP code *<input name="zip" autocomplete="postal-code" required pattern="[0-9]{5}(-[0-9]{4})?" maxlength="10" value="${esc(contact.zip)}"></label><label class="commerce-field">Project timeline<select name="timeline"><option>Just exploring</option>${['Within 1–3 months','Within 3–6 months','More than 6 months away'].map(v=>`<option ${contact.timeline===v?'selected':''}>${v}</option>`).join('')}</select></label><details><summary>Measurements, photos or plans (optional)</summary><p>Attach them in your email app when you send your request. This prototype does not upload files.</p></details><p class="caption">This prototype prepares an email brief. No form data is sent automatically. You review and send it in your email app.</p><button class="btn" type="submit">Prepare My Quote Request</button></form>`;
 root.innerHTML=(flowNotice?'<p class="notice" role="status">'+esc(flowNotice)+'</p>':'')+(p&&requestKeys().length>1&&config.step>0&&config.step<5?'<p class="eyebrow">Version '+(requestKeys().indexOf(keyOf(config))+1)+' of '+requestKeys().length+' · '+esc(cabinetLabel(config))+'</p>':'')+html;updateSummary();bind();if(scroll){$('h2',root)?.focus({preventScroll:true});const top=$('.commerce-shell').getBoundingClientRect().top+scrollY-$('.header').offsetHeight-18;window.scrollTo({top,behavior:'instant'});}}
 function stableRender(){const y=scrollY;const focused=document.activeElement;const attrs=['data-product','data-style','data-finish','data-dimension','data-accessory-id','data-material-choice'];const attr=attrs.find(a=>focused?.hasAttribute(a));const selector=attr?'['+attr+'="'+focused.getAttribute(attr)+'"]'+(attr==='data-dimension'?'[data-value="'+focused.dataset.value+'"]':attr==='data-material-choice'?'[data-material-value="'+focused.dataset.materialValue+'"]':''):null;const open=[...root.querySelectorAll('details')].map(d=>d.open);render();root.querySelectorAll('details').forEach((d,i)=>d.open=!!open[i]);if(selector)$(selector,root)?.focus({preventScroll:true});window.scrollTo({top:y,behavior:'instant'});}
 function addCurrent(){const message=validateConfiguration(config);if(message){error(message);return false;}const item=structuredClone(config);delete item.step;delete item.editIndex;if(config.editIndex!==undefined&&keyOf(project[config.editIndex])===keyOf(config)){project[config.editIndex]=item;}else {const existing=project.findIndex(c=>keyOf(c)===keyOf(item));if(existing<0){project.push(item);config.editIndex=project.length-1;}else {project[existing]=item;config.editIndex=existing;}}rememberCabinet();save();return true;}
 function showStorageFinder(id){
 const accessory=accessories.find(a=>a.id===id);if(!accessory)return;rememberCabinet();save();$('.config-progress').hidden=true;$('.plan-nav').hidden=true;
 const matches=filterProducts({storage:id});
 root.innerHTML='<div class="storage-finder"><button type="button" class="textlink" id="return-to-request">← Back to my request</button><div class="storage-finder-context"><img src="/assets/'+accessory.image+'" alt="'+esc(accessory.name)+' illustrative storage"><div><span class="eyebrow">Storage you’re planning</span><h2 tabindex="-1">'+esc(accessory.name)+'</h2><p>'+esc(accessory.purpose)+'</p><p class="caption">You’re finding a match for your current request. Your existing cabinets and finishes stay saved.</p></div></div><h3>Compatible cabinet planning models</h3><p class="caption">Choose a suitable width, then add the storage and cabinet together. Factory fit still needs confirmation.</p><div class="config-options">'+matches.map(p=>{const widths=p.widths.filter(w=>compatibility(p,w,accessory).ok);const existing=p.id===config.product?config:requestKeys().map(draftFor).find(c=>c?.product===p.id);const width=widths.includes(existing?.width)?existing.width:widths[0];return '<article class="component-card finder-cabinet" data-finder-product="'+p.id+'" data-finder-width="'+width+'">'+productSvg(p,{width,finish:existing?.finish})+'<h3>'+esc(p.name)+'</h3><p>'+esc(p.description)+'</p><div class="config-chips" role="group" aria-label="Compatible widths for '+esc(p.name)+'">'+widths.map(w=>'<button type="button" data-finder-width-choice="'+w+'" aria-pressed="'+(w===width)+'">'+w+'″</button>').join('')+'</div><p class="caption">'+(existing?'Keeps this cabinet’s existing color and materials.':'Choose this cabinet’s own color and materials next.')+'</p><button type="button" class="btn outline" data-add-storage-cabinet="'+p.id+'">'+(p.id===config.product?'Use for this cabinet':selectedTypes.includes(p.id)?'Use with cabinet in my request':'Add to my request')+'</button></article>';}).join('')+'</div></div>';
 $('#return-to-request').addEventListener('click',()=>{ $('.config-progress').hidden=false;$('.plan-nav').hidden=false;render(true);});
 $$('[data-finder-width-choice]',root).forEach(button=>button.addEventListener('click',()=>{const card=button.closest('[data-finder-product]');card.dataset.finderWidth=button.dataset.finderWidthChoice;$$('[data-finder-width-choice]',card).forEach(b=>b.setAttribute('aria-pressed',String(b===button)));}));
 $$('[data-add-storage-cabinet]',root).forEach(button=>button.addEventListener('click',()=>{const p=byId(button.dataset.addStorageCabinet);const width=Number(button.closest('[data-finder-product]').dataset.finderWidth);if(!compatibility(p,width,accessory).ok)return;const existing=p.id===config.product?config:requestKeys().map(draftFor).find(c=>c?.product===p.id);const draft={...blank(),...(existing?structuredClone(existing):{}),product:p.id,width,depth:existing?.depth||p.depths[0],height:existing?.height||p.heights[0],step:1};draft.accessories=[...new Set([...(draft.accessories||[]).filter(a=>compatibility(p,width,accessories.find(x=>x.id===a)).ok),id])];if(!selectedTypes.includes(p.id))selectedTypes.push(p.id);cabinetDrafts[keyOf(draft)]=draft;if(p.id===config.product)config={...draft,step:3};else{const i=project.findIndex(c=>keyOf(c)===keyOf(draft));if(i>=0&&!validateConfiguration(draft)){project[i]=structuredClone(draft);cabinetDrafts[keyOf(draft)].editIndex=i;}}flowNotice=p.id===config.product?accessory.name+' is now selected for this cabinet.':p.name+' with '+accessory.name+' added to your request. Its own finish choices stay separate.';$('.config-progress').hidden=false;$('.plan-nav').hidden=false;save();render(true);}));
 $('h2',root)?.focus({preventScroll:true});const top=$('.commerce-shell').getBoundingClientRect().top+scrollY-$('.header').offsetHeight-18;window.scrollTo({top,behavior:'instant'});
 }
 function renderQuantityOptions(){const target=$('#quantity-color-options',root);if(!target)return;target.innerHTML=Number.isInteger(config.quantity)&&config.quantity>1&&config.quantity<=99?'<p class="notice">Need these '+config.quantity+' cabinets in different colors? Split the quantity into separate versions; the total stays '+config.quantity+'.</p><button type="button" class="btn outline" id="split-quantity">Split quantity into color versions</button>':'';$('#split-quantity')?.addEventListener('click',splitQuantity);}
 function newVersion(quantity){const clone=structuredClone(config);clone.instanceId=config.product+'::'+crypto.randomUUID();clone.quantity=quantity;clone.finish='';clone.doorMaterial='';clone.step=2;delete clone.editIndex;return clone;}
 function splitQuantity(){const total=config.quantity;if(!Number.isInteger(total)||total<2||total>99)return error('Enter a quantity from 2 to 99 to split.','#config-quantity');const extra=newVersion(total-1);config.quantity=1;cabinetDrafts[keyOf(extra)]=extra;rememberCabinet();flowNotice='Quantity '+total+' split into two color versions: 1 and '+(total-1)+'. Choose a finish for each; the total quantity is unchanged.';config.step=2;save();render(true);}
 function addAnotherColor(){if(config.quantity>1)return splitQuantity();if(!validateConfiguration(config))addCurrent();const extra=newVersion(1);rememberCabinet();cabinetDrafts[keyOf(extra)]=extra;config=extra;flowNotice='Added one cabinet in a separate color version. Size, door style, box material and storage were copied; choose its own color and door material.';save();render(true);}
 function removeVersion(id){
 rememberCabinet();const draft=draftFor(id)|| (byId(id)?{...blank(),product:id,width:byId(id).widths[0],depth:byId(id).depths[0],height:byId(id).heights[0]}:null);if(!draft)return;
 const product=draft.product,label=cabinetLabel(draft),active=keyOf(config)===id;
 removedCabinet={id,draft:structuredClone(draft),entry:project.find(c=>keyOf(c)===id)?structuredClone(project.find(c=>keyOf(c)===id)):null,index:project.findIndex(c=>keyOf(c)===id),typeIndex:selectedTypes.indexOf(product)};
 project=project.filter(c=>keyOf(c)!==id);delete cabinetDrafts[id];
 if(active){const notes=config.notes;config={...blank(),notes};}
 if(!Object.values(cabinetDrafts).some(c=>c.product===product)&&!project.some(c=>c.product===product))selectedTypes=selectedTypes.filter(p=>p!==product);
 reindexDrafts();
 if(active){const next=requestKeys()[0];if(next){const nextDraft=draftFor(next);if(nextDraft)config={...blank(),...structuredClone(nextDraft),step:nextDraft.finish?2:1};else{setProduct(next);config.step=1;}}}
 if(!requestKeys().length&&!helpOnly){config.step=0;}
 removalMessage=label+' removed from your plan.';flowNotice='';save();render(false);$('#undo-cabinet-removal')?.focus({preventScroll:true});
 }
 function reindexDrafts(){for(const draft of [config,...Object.values(cabinetDrafts)]){const i=project.findIndex(c=>keyOf(c)===keyOf(draft));if(i<0)delete draft.editIndex;else if(draft.editIndex!==undefined)draft.editIndex=i;}}
 function undoRemoval(){if(!removedCabinet)return;const removed=removedCabinet;rememberCabinet();let restored=structuredClone(removed.draft),entry=removed.entry&&structuredClone(removed.entry);
 if(requestKeys().includes(removed.id)){restored.instanceId=restored.product+'::'+crypto.randomUUID();if(entry)entry.instanceId=restored.instanceId;}
 if(!selectedTypes.includes(restored.product))selectedTypes.splice(Math.max(0,removed.typeIndex),0,restored.product);
 cabinetDrafts[keyOf(restored)]=restored;if(entry)project.splice(removed.index<0?project.length:Math.min(removed.index,project.length),0,entry);
 if(!config.product){config={...blank(),...restored};if(config.step===5)config.step=4;}
 reindexDrafts();removedCabinet=null;removalMessage='Cabinet restored. Your color, size, quantity and storage choices are back.';save();render(false);
 }

 function bind(){
 renderQuantityOptions();$('#another-color')?.addEventListener('click',addAnotherColor);$('#remove-current-version')?.addEventListener('click',()=>removeVersion(keyOf(config)));

 $$('[data-find-storage]',root).forEach(button=>button.addEventListener('click',()=>showStorageFinder(button.dataset.findStorage)));

 $$('[data-product]',root).forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.product;if(selectedTypes.includes(id)){selectedTypes=selectedTypes.filter(v=>v!==id);project=project.filter(c=>c.product!==id);for(const draft of [config,...Object.values(cabinetDrafts)]){const i=project.findIndex(c=>keyOf(c)===keyOf(draft));if(i<0)delete draft.editIndex;else if(draft.editIndex!==undefined)draft.editIndex=i;}}else selectedTypes=[...selectedTypes,id];helpOnly=false;save();stableRender();}));
 $('#design-help')?.addEventListener('click',()=>{helpOnly=true;go(4);});
 $$('[data-dimension]',root).forEach(b=>b.addEventListener('click',()=>{config[b.dataset.dimension]=Number(b.dataset.value);config.accessories=config.accessories.filter(id=>compatibility(byId(config.product),config.width,accessories.find(a=>a.id===id)).ok);save();stableRender();}));
 $('#config-quantity')?.addEventListener('input',e=>{config.quantity=Number(e.target.value);save();renderQuantityOptions();});$('#custom-size')?.addEventListener('input',e=>{config.customSize=e.target.value;save();});
 $$('[data-finish]',root).forEach(b=>b.addEventListener('click',()=>{config.finish=b.dataset.finish;config.doorMaterial='';save();stableRender();}));$$('[data-style]',root).forEach(b=>b.addEventListener('click',()=>{config.style=b.dataset.style;save();stableRender();}));
 $$('[data-material-choice]',root).forEach(button=>{button.addEventListener('click',()=>{config[button.dataset.materialChoice]=button.dataset.materialValue;save();stableRender();});button.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(event.key))return;event.preventDefault();const buttons=$$('[data-material-choice="'+button.dataset.materialChoice+'"]',root);let i=buttons.indexOf(button);i=event.key==='Home'?0:event.key==='End'?buttons.length-1:(i+(['ArrowRight','ArrowDown'].includes(event.key)?1:-1)+buttons.length)%buttons.length;buttons[i].focus({preventScroll:true});buttons[i].click();});});
 $$('[data-accessory-id]',root).forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.accessoryId;if(!compatibility(byId(config.product),config.width,accessories.find(a=>a.id===id)).ok)return;config.accessories=config.accessories.includes(id)?config.accessories.filter(a=>a!==id):[...config.accessories,id];save();stableRender();}));
 $$('[data-review-edit]',root).forEach(b=>b.addEventListener('click',()=>go(Number(b.dataset.reviewEdit))));$('#add-project')?.addEventListener('click',()=>{if(addCurrent())stableRender();});$('#another-cabinet')?.addEventListener('click',()=>{rememberCabinet();config=blank();selectedTypes=[];cabinetDrafts={};helpOnly=false;go(0);});$('#download-review')?.addEventListener('click',download);
 $$('[data-project-color]',root).forEach(button=>button.addEventListener('click',()=>{rememberCabinet();const i=Number(button.dataset.projectColor);config={...blank(),...structuredClone(cabinetDrafts[keyOf(project[i])]||project[i]),editIndex:i};go(2);}));
 $$('[data-project-edit]',root).forEach(b=>b.addEventListener('click',()=>{const i=Number(b.dataset.projectEdit);config={...structuredClone(project[i]),step:4,editIndex:i};go(1);}));$$('[data-project-remove]',root).forEach(b=>b.addEventListener('click',()=>{removeVersion(keyOf(project[Number(b.dataset.projectRemove)]));}));$('#installation')?.addEventListener('change',e=>{contact.installation=e.target.value;save();});$('#project-notes')?.addEventListener('input',e=>{config.notes=e.target.value;save();});
 const form=$('#quote-contact');form?.addEventListener('input',()=>{for(const [k,v]of new FormData(form))contact[k]=String(v);save();});form?.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity()||form.dataset.preparing)return;form.dataset.preparing='true';$('button[type=submit]',form).disabled=true;for(const[k,v]of new FormData(form))contact[k]=String(v);save();sessionStorage.setItem('amber-prepared-quote',JSON.stringify({text:reference(),name:contact.name}));location.href='/quote-confirmation/';});
 }
 $('.config-progress').addEventListener('click',e=>{const b=e.target.closest('[data-config-step]');if(!b||b.disabled)return;go(Number(b.dataset.configStep));});
 $('#config-back').addEventListener('click',()=>go(helpOnly&&config.step===4?0:Math.max(0,config.step-1)));
 $('#config-next').addEventListener('click',()=>{if(config.step===0){if(!selectedTypes.length)return error('Select at least one cabinet type, or choose design help.');const next=requestKeys().find(id=>!project.some(c=>keyOf(c)===id))||requestKeys()[0];openCabinet(next);return;}if(config.step===1&&(!Number.isInteger(config.quantity)||config.quantity<1||config.quantity>99))return error('Enter a quantity from 1 to 99.','#config-quantity');if(config.step===2){const message=validateConfiguration(config);if(message)return error(message,!config.style?'[data-style]':!config.finish?'[data-finish]':!config.doorMaterial?'#door-material':!config.boxMaterial?'#box-material':'#door-material');}if(config.step===4){if(!helpOnly&&!addCurrent())return;const next=!helpOnly&&pendingType();if(next){openCabinet(next);return;}go(5);}else go(config.step+1);});
 function fresh(){config=blank();project=[];contact={};helpOnly=false;selectedTypes=[];cabinetDrafts={};const params=new URLSearchParams(location.search);let p=byId(params.get('product'));const storage=accessories.find(a=>a.id===params.get('storage')||a.purpose===params.get('storage'));if(!p&&storage)p=filterProducts({storage:storage.id})[0];if(p){selectedTypes=[p.id];setProduct(p.id);if(params.has('width')&&p.widths.includes(Number(params.get('width'))))config.width=Number(params.get('width'));if(storage&&!compatibility(p,config.width,storage).ok)config.width=p.widths.find(w=>compatibility(p,w,storage).ok)||config.width;if(storage&&compatibility(p,config.width,storage).ok)config.accessories=[storage.id];config.step=1;}const f=finishes.find(f=>f.id===params.get('finish')||f.name===params.get('color'));if(f)config.finish=f.id;if(p?.styles.includes(params.get('style')))config.style=params.get('style');if(f?.doorMaterials.includes(params.get('material')))config.doorMaterial=params.get('material');if(params.get('custom')==='1')config.customSize='I would like to discuss a specific size or color.';if(params.get('fromSurvey')==='1'){const survey=read('amber-plan',{});contact.timeline=survey.timeline||'';config.notes=[survey.intent,survey.location,survey.budget].filter(Boolean).join(' · ');}if(params.get('layout'))config.notes='Kitchen scale: '+params.get('layout')+' (planning preference) · ';if(params.get('help')==='design'){helpOnly=true;config.step=4;}if(params.get('location'))config.notes+='Project location: '+params.get('location');save();render();}
 if(saved?.config){restoreBatch();config={...blank(),...saved.config};project=Array.isArray(saved.project)?saved.project:[];contact=saved.contact||{};helpOnly=!!saved.helpOnly;$('#draft-choice').hidden=false;$('#draft-choice').innerHTML='<h3>You have an unfinished cabinet plan.</h3><p>Continue your saved choices or start fresh from this page.</p><button class="btn" id="resume-config">Resume my project</button> <button class="btn outline" id="new-config">Start a new configuration</button>';$('.config-progress').hidden=true;$('.plan-nav').hidden=true;$('#resume-config').addEventListener('click',()=>{restoreBatch();config={...blank(),...saved.config};config.step=Math.min(5,Math.max(0,config.step||0));project=Array.isArray(saved.project)?saved.project:[];contact=saved.contact||{};helpOnly=!!saved.helpOnly;if(config.product&&!byId(config.product))config=blank();config.accessories=(config.accessories||[]).filter(id=>accessories.some(a=>a.id===id));$('#draft-choice').hidden=true;$('.config-progress').hidden=false;$('.plan-nav').hidden=false;render();});$('#new-config').addEventListener('click',()=>{$('#draft-choice').hidden=true;$('.config-progress').hidden=false;$('.plan-nav').hidden=false;fresh();});updateSummary();}else fresh();
}
if($('#prepared-request')){let request;try{request=JSON.parse(sessionStorage.getItem('amber-prepared-quote'));}catch{}if(request){$('#prepared-request').innerHTML=`<h2>Your quote brief is ready.</h2><p>It has not been sent to Amber Leaf. Review the email, attach any plans or photos, and send it from your email app.</p><div class="inline-actions"><a class="btn" href="mailto:info@amberleafhome.us?subject=${encodeURIComponent('Amber Leaf — Cabinet Quote Request')}&body=${encodeURIComponent(request.text)}">Open Email to Amber Leaf</a><button class="btn outline" id="prepared-download">Download my brief</button></div><details><summary>Review the prepared brief</summary><pre>${esc(request.text)}</pre></details><h3>After you send it</h3><p>The team will review scope, measurements and product options. Agree on specifications and receive a written quote before approval, manufacturing or payment. No response deadline is promised.</p>`;$('#prepared-download').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([request.text],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='amber-leaf-quote-brief.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});}else $('#prepared-request').innerHTML='<p>No prepared request on this browser. <a href="/start-order/">Build your cabinet plan</a> to begin.</p>';}

const closeCommerceMenus=()=>{$$('.mega').forEach(p=>p.hidden=true);$$('[data-menu]').forEach(b=>b.setAttribute('aria-expanded','false'));};document.addEventListener('keydown',e=>{if(e.key==='Escape')closeCommerceMenus();});document.addEventListener('click',e=>{if(!e.target.closest('.header'))closeCommerceMenus();});$$('.mega-close').forEach(b=>b.addEventListener('click',closeCommerceMenus));

if(path.startsWith('/cabinets/')&&!$('#component-grid')){const params=new URLSearchParams(location.search);$$('a[href^="/start-order/?product="]').forEach(a=>{const target=new URL(a.href);for(const[k,v]of params)target.searchParams.set(k,v);a.href=target.pathname+target.search;});}

$$('[data-illustrated-process]').forEach(section=>{const button=$('.process-motion-toggle',section);button?.addEventListener('click',()=>{const paused=section.classList.toggle('motion-paused');button.setAttribute('aria-pressed',String(paused));button.textContent=paused?'Play illustrations':'Pause illustrations';});});

$$('.business-highlight').forEach(note=>note.addEventListener('toggle',()=>{if(note.open)$$('.business-highlight').forEach(other=>{if(other!==note)other.open=false;});}));
